"""Parse a recorded status line without network access."""

def status_code(line: str) -> int:
    """Return a valid observed status or raise ValueError."""
    parts = line.split()
    if len(parts) < 2 or parts[0] not in ("HTTP/1.0", "HTTP/1.1"):
        raise ValueError("Invalid status line")
    code = int(parts[1])
    if not 100 <= code <= 599:
        raise ValueError("Invalid status code")
    return code

